export function validRun(r){if(r?.schemaVersion!=='strategic-coupling/1.0'||r.roles?.length!==6||!r.candidates?.length||!r.spotlight?.event)throw Error('Invalid run');return r;}
export function pairEvidence(r,a,b){const i=r.candidates.findIndex(x=>x.id===a),j=r.candidates.findIndex(x=>x.id===b);if(i<0||j<0)throw Error('Unknown candidate');const n=r.pairIndices.findIndex(p=>p[0]===Math.min(i,j)&&p[1]===Math.max(i,j));const ds=i===j?0:r.distances.spectrum[n],dt=i===j?0:r.distances.transport[n];return {eventId:'D-'+[a,b].sort().join('-'),candidateIds:[a,b],owners:['spectrum','transport'],delta:Math.abs(ds-dt),normalizedDistances:{spectrum:ds,transport:dt},normalizationVersion:r.calibration.version,claim:'Spectrum versus measured labelled-port response discrepancy.',artifactIds:[a+'-spectrum',b+'-transport'],requestedTest:'Compare loop product and explicit gauge/permutation/port controls.',uncertainty:'A distance discrepancy does not establish a mechanism.'};}
export function routePreview(packet,threshold,budget=12){const cost=3,proxy=packet.delta*.5/(1+cost);if(packet.delta<threshold)return {status:'suppressed',reason:'below_threshold',members:[],budget};if(proxy<.1)return {status:'suppressed',reason:'below_voi_proxy',members:[],budget};if(budget<cost)return {status:'suppressed',reason:'communication_budget',members:[],budget};return {status:'opened',members:['spectrum','transport','gauge'],budget:budget-cost,proxy};}
const words=x=>typeof x==='string'?x:JSON.stringify(x,null,2);
export async function mountLab(doc,fetcher,download){
 const $=id=>doc.getElementById(id),el=(tag,text,cls)=>{const n=doc.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
 try{
  const rs=await Promise.all(['run.json','agent-run.json'].map(async f=>{const x=await fetcher('./'+f);if(!x.ok)throw Error('HTTP '+x.status);return x.json();}));const r=validRun(rs[0]),agents=rs[1];let selectedWorker='spectrum',currentPacket=r.spotlight.event,budget=12;
  for(const [num,label,scope] of [[r.candidates.length,'Candidate evaluations','Fixed, deliberately constructed pool'],[r.candidates.length*7,'Scattering solves','3 observed + 4 held-out settings'],[agents.firstPasses.length,'Actual worker first passes','Salted commitments before reveal'],[agents.coalitionOutputs.length,'Bounded coalition outputs','Proposals · review pending']]){const n=el('div');n.append(el('span',label,'stat-label'),el('strong',String(num)),el('small',scope));$('stats').append(n);}
  for(const x of r.candidates)for(const id of ['candidate-a','candidate-b']){const o=el('option',x.id+' · '+(x.detuned?'detuned':'symmetric')+' · φ='+x.phi.toFixed(2)+(x.gaugeCopy?' · gauge copy':''));o.value=x.id;$(id).append(o);}
  $('candidate-a').value=r.spotlight.plus;$('candidate-b').value=r.spotlight.minus;$('energy').value='1';
  const matrix=(id,t)=>{const n=$(id);n.replaceChildren(el('span','out / in','axis'));for(let j=0;j<3;j++)n.append(el('span',String(j),'axis'));for(let i=0;i<3;i++){n.append(el('span',String(i),'axis'));for(let j=0;j<3;j++){const v=t[i][j],c=el('div',v.toFixed(3),'cell');c.style.backgroundColor='hsl(155 28% '+(96-v*57)+'%)';c.style.color=v>.6?'#fff':'#263b31';c.setAttribute('aria-label','Output '+i+', input '+j+': '+v.toFixed(6));n.append(c);}}};
  const spectrum=(id,values)=>{const n=$(id);n.replaceChildren(el('p','Eigenvalues: '+values.map(v=>v.toFixed(6)).join(' · '),'eigenvalues'));const track=el('div',undefined,'spectrum-track');for(const v of values){const tick=el('span',undefined,'spectrum-tick');tick.style.left=((v+2.5)/5*100)+'%';track.append(tick);}n.append(track);};
  const pair=()=>{const a=r.candidates.find(x=>x.id===$('candidate-a').value),b=r.candidates.find(x=>x.id===$('candidate-b').value),e=Number($('energy').value);for(const [suffix,x] of [['a',a],['b',b]]){$('title-'+suffix).textContent=x.id+' · '+(x.detuned?'distinct onsite values':'symmetric onsite values');$('details-'+suffix).textContent='φ='+x.phi.toFixed(6)+' · onsite ['+x.onsite.join(', ')+'] · γ=2'+(x.gaugeCopy?' · diagonal gauge copy':'');spectrum('spectrum-'+suffix,x.eigenvalues);matrix('matrix-'+suffix,x.transport[e]);$('quality-'+suffix).textContent='Eigen residual '+x.quality.eigenResidual.toExponential(2)+' · unitarity error '+x.quality.unitarityError.toExponential(2);}
   currentPacket=pairEvidence(r,a.id,b.id);const eig=Math.max(...a.eigenvalues.map((v,i)=>Math.abs(v-b.eigenvalues[i])));let response=0;for(let i=0;i<3;i++)for(let j=0;j<3;j++)response+=(a.transport[e][i][j]-b.transport[e][i][j])**2;
   $('pair-summary').textContent='Max eigenvalue difference: '+eig.toExponential(3)+'\nResponse Frobenius difference at selected E: '+Math.sqrt(response).toFixed(6)+'\nCalibrated spectrum distance '+currentPacket.normalizedDistances.spectrum.toFixed(3)+' · response distance '+currentPacket.normalizedDistances.transport.toFixed(3)+' · disagreement Δ='+currentPacket.delta.toFixed(3)+'.\nDistances use all three observed energies; the heatmap shows the selected one.';};
  for(const id of ['candidate-a','candidate-b','energy'])$(id).addEventListener('change',pair);pair();
  const nodes=[];const titles={geometry:'Geometry',spectrum:'Spectrum',gauge:'Gauge / loop',transport:'Transport',archive:'QD / archive',skeptic:'Numerical skeptic'};
  const worker=()=>{const state=r.localStates[selectedWorker],pass=agents.firstPasses.find(x=>x.worker===selectedWorker),n=$('worker-detail');n.replaceChildren(el('p','OWN VIEW · '+selectedWorker+'/1.0','eyebrow'),el('h3',titles[selectedWorker]));n.append(el('h4','Actual first-pass claim'),el('p',words(pass.draft.scopedClaim)),el('h4','Information this view loses'),el('p',words(pass.draft.informationLost)),el('h4','First five own observations'),el('pre',JSON.stringify(state.observations.slice(0,5),null,2)),el('h4','Committed before reveal'),el('p',pass.commitment),el('p','H can inspect these exported structured records. Other workers received their own packets; the router accepts published envelopes only. This is procedural isolation.'));for(const node of nodes)node.setAttribute('aria-pressed',String(node.dataset.worker===selectedWorker));};
  for(const role of r.roles){const b=el('button',titles[role]);b.dataset.worker=role;b.dataset.active='false';b.append(el('small','separate local view'));b.addEventListener('click',()=>{selectedWorker=role;worker();});nodes.push(b);$('network').append(b);}worker();
  const threshold=()=>$('threshold-label').textContent=Number($('threshold').value).toFixed(2);$('threshold').value='0.7';$('threshold').addEventListener('input',threshold);threshold();
  $('route-pair').addEventListener('click',()=>{const result=routePreview(currentPacket,Number($('threshold').value),budget);budget=result.budget;for(const b of nodes)b.dataset.active=String(result.members.includes(b.dataset.worker));$('route-status').textContent=result.status==='opened'?'Opened a local 3-member coalition: '+result.members.join(', ')+'. Remaining communication units: '+budget+'. Awaiting an external bounded output; no model was called.':'Suppressed: '+result.reason+'. Remaining communication units: '+budget+'.';});
  $('download-packet').addEventListener('click',()=>download(currentPacket.eventId+'.json',currentPacket));
  for(const o of agents.coalitionOutputs){const n=el('article');n.append(el('h4',o.worker+' · '+o.output.kind),el('p',words(o.output.scopedClaim)),el('p','Changed after exchange: '+words(o.output.whatChangedFromOwnFirstPass)),el('p','Failure criterion: '+words(o.output.failureCriterion)),el('p','Status: proposed · no shared schema promotion'));$('agent-results').append(n);}
  const table=(heads,rows)=>{const wrap=el('div',undefined,'table-scroll'),t=el('table',undefined,'archive-table'),thead=el('thead'),tr=el('tr');for(const h of heads)tr.append(el('th',h));thead.append(tr);t.append(thead);const body=el('tbody');for(const row of rows){const tr=el('tr');for(const c of row)tr.append(el('td',String(c)));body.append(tr);}t.append(body);wrap.append(t);return wrap;};
  const tabs=[];const archive=name=>{for(const b of tabs)b.setAttribute('aria-pressed',String(b.dataset.archive===name));const n=$('archive-view');n.replaceChildren();if(name==='matter'){n.append(el('p','Frozen circulation / reflection bins, numerical validity gate; no adaptive search.','micro-copy'),table(['Behavioral niche','Candidate','Task quality'],Object.entries(r.archives.matter).map(([k,v])=>[k,v.candidateId,v.quality.toFixed(4)])));}else if(name==='representation'){n.append(el('p','Six local vocabularies coexist. Utility scores and global schema promotion remain unassigned.','micro-copy'),table(['Representation','State','Held-out utility'],r.archives.representation.map(x=>[x.id,x.status,x.heldOutUtility===null?'Not calibrated':x.heldOutUtility])));}else{n.append(el('p','Deterministic evidence replay: equal candidate/solver charges, zero model tokens. Message counts are protocol units. Behavioral coverage and AI superiority are unmeasured.','micro-copy'),table(['Mode','Candidate charges','Scattering charges','Messages','LLM tokens','Discovery advantage'],r.archives.swarm.map(x=>[x.mode,x.candidateEvaluations,x.scatteringSolves,x.messages,x.llmTokens,'Unmeasured'])));}};
  for(const [key,title] of [['matter','Matter'],['representation','Representations'],['swarm','Communication policies']]){const b=el('button',title);b.dataset.archive=key;b.addEventListener('click',()=>archive(key));tabs.push(b);$('archive-tabs').append(b);}archive('matter');
  const loss=r.representationLoss;$('loss-diagnostic').textContent='Representation-loss diagnostic on the constructed pool: spectrum-only merging makes '+loss.spectrumOnly.falseMergesAgainstHeldOutFixedPortResponse+' false merges among '+loss.spectrumOnly.predictedEquivalentPairs+' predicted-equivalent pairs. Adding the loop product and onsite arrangement makes '+loss.spectrumPlusLoopAndOnsite.falseMergesAgainstHeldOutFixedPortResponse+' among '+loss.spectrumPlusLoopAndOnsite.predictedEquivalentPairs+'. Held-out energies and port widths judge the fixed-port response. This is not a four-arm AI performance comparison.';
  $('diversity-diagnostic').textContent='Centered distance-fingerprint effective rank: '+r.fingerprintDiversity.effectiveRank.toFixed(3)+'. This measures differences on these probes, not independence or quality. Identical fingerprints give zero. Graph Laplacian entropy is not used as agent diversity.';
  for(const s of [...r.limits,'Actual worker model family, simulator and curated pool are shared. Token usage for the recorded Codex contexts is unavailable; it is not reported as zero.','Browser QA was unavailable; mathematical, protocol and DOM checks are provided.'])$('limitations').append(el('li',s));
  $('lab-content').hidden=false;$('load-status').hidden=true;return {run:r,agents,pair,archive};
 }catch(e){$('load-status').textContent='The Swarm Lab could not be loaded. '+e.message;$('load-status').className='load-status error';return null;}
}
function save(name,data){const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)+'\n'],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
if(typeof document!=='undefined')mountLab(document,fetch,save);
